tmCustomCss:
木木｜手札留白（可二改自用🈲二传）
此时此刻美化（糯叽机）

/* ==========================================
   一、全屏底色与安全区域适配（无字体限制）
   ========================================== */
#this-moment-screen {
    background: #f2f1ed !important; 
    color: #111111 !important;
}

.tm-bg-overlay {
    background: #f2f1ed !important;
    opacity: 1 !important;
}

.tm-bg-image {
    display: none !important;
}

.tc-deco-top, .tc-deco-bottom, .tc-deco-left, .tc-deco-right, .tc-watermark {
    display: none !important;
}

/* 故事内容流区域 */
.tm-story {
    padding: calc(env(safe-area-inset-top, 20px) + 65px) 16px 140px 16px !important;
    background: transparent !important;
}

/* ==========================================
   二、顶部导航栏大容器（勿动）
   ========================================== */
.tm-header {
    background: #ffffff !important;
    border: 1px solid #e2e0da !important;
    border-radius: 16px !important;

    position: fixed !important;
    top: 0 !important;
    left: 14px !important;
    right: 14px !important;
    z-index: 999 !important;

    height: 52px !important; 
    margin-top: env(safe-area-inset-top, 20px) !important; 
    padding: 0 12px !important;

    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.03) !important;

    display: flex !important;
    flex-direction: row !important;
    justify-content: space-between !important;
    align-items: center !important;
    overflow: visible !important;
}

.tm-header > .tm-btn-icon:first-child {
    display: block !important;
    opacity: 0 !important; 
    background: transparent !important;
    width: 35px !important;
    height: 100% !important;
    flex-shrink: 0 !important;
}

.tm-header-right {
    display: flex !important;
    align-items: center !important;
    justify-content: flex-end !important;
    width: 35px !important;
    height: 100% !important;
    flex-shrink: 0 !important;
}
.tm-header-right > .tm-btn-icon:first-child {
    display: none !important; 
}
.tm-header-right > .tm-btn-icon:last-child {
    background: transparent !important;
    color: #444444 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 32px !important;
    height: 32px !important;
}
.tm-header-right > .tm-btn-icon:last-child::before {
    content: "📎" !important;
    font-size: 16px !important;
}
.tm-header-right > .tm-btn-icon:last-child svg,
.tm-header-right > .tm-btn-icon:last-child i {
    display: none !important;
}

/* ==========================================
   三、中心分流（勿动）
   ========================================== */
.tm-header-center {
    display: flex !important;
    flex-direction: row !important;
    flex-grow: 1 !important;
    height: 100% !important;
    align-items: center !important;
    justify-content: space-between !important;
    background: transparent !important;
    border: none !important;
    margin: 0 8px !important;
    padding: 0 !important;
    overflow: visible !important;
}

.tm-top-vs {
    display: none !important;
}

.tm-top-drop-btn {
    display: flex !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 8px !important;
    height: 100% !important;
    background: transparent !important;
    border: none !important;
}
.tm-header-avatar {
    width: 35px !important;
    height: 35px !important;
    border-radius: 50% !important;
    border: 1px solid #e2e0da !important;
    object-fit: cover !important;
}
.tm-header-name {
    font-size: 15px !important;
    font-weight: 600 !important;
    color: #111111 !important;
}

.tm-top-drop-btn-user {
    flex: 1 !important;
    height: 100% !important;
    background: transparent !important;
    border: none !important;
    display: flex !important;
    justify-content: flex-end !important;
    align-items: center !important;
    overflow: visible !important;
}

.tm-top-drop-btn-user > img,
.tm-top-drop-btn-user > div,
.tm-top-drop-btn-user > span,
.tm-top-drop-btn-user > i,
.tm-top-drop-btn-user > svg,
.tm-top-drop-btn-user > .tm-header-avatar,
.tm-top-drop-btn-user > .tm-header-name,
.tm-top-drop-btn-user > [class*="avatar"],
.tm-top-drop-btn-user > [class*="name"] {
    display: none !important; 
}

.tm-top-drop-btn-user .dropdown-menu,
.tm-top-drop-btn-user [class*="menu"],
.tm-top-drop-btn-user [class*="drop"] {
    display: block !important;
    position: absolute !important;
    top: 100% !important;
    right: 0 !important;
    z-index: 99999 !important;
}

.tm-top-drop-btn-user .dropdown-menu img,
.tm-top-drop-btn-user [class*="menu"] img,
.tm-top-drop-btn-user .dropdown-menu [class*="avatar"],
.tm-top-drop-btn-user [class*="menu"] [class*="avatar"] {
    display: none !important; 
}

.tm-top-drop-btn-user .dropdown-menu *,
.tm-top-drop-btn-user [class*="menu"] *,
.tm-top-drop-btn-user [class*="drop"] * {
    display: flex !important;
    color: #111111 !important;
    font-size: 14px !important;
}

/* ==========================================
   四、卡片式布局与纸张层叠阴影（勿动）
   ========================================== */
.tm-para {
    background: transparent !important;
    margin-bottom: 24px !important;
    padding: 0 !important;
}

.tm-para-char, .tm-para-user {
    background: #ffffff !important;
    border: 1px solid #e8e6df !important;
    border-radius: 16px !important;
    padding: 20px !important;
    position: relative !important;
    box-shadow: 
        0 1px 1px rgba(0,0,0,0.04),
        0 4px 12px rgba(0,0,0,0.02),
        0 12px 24px -4px rgba(0,0,0,0.03) !important;
}

.tm-para-char::after, .tm-para-user::after {
    content: "" !important;
    position: absolute !important;
    z-index: -1 !important;
    left: 8px !important;
    right: 8px !important;
    bottom: -5px !important;
    height: 10px !important;
    background: #ffffff !important;
    border: 1px solid #e8e6df !important;
    border-radius: 12px !important;
}

/* ==========================================
   五、气泡内 Header 重构（✨日期与小字统统放开调整）
   ========================================== */
.tc-header {
    display: block !important;
    border-bottom: 1px dashed #e8e6df !important;
    padding-bottom: 10px !important;
    margin-bottom: 14px !important;

    /* 🛠️ 【自定义控制台】直接在这儿自由调整日期数字、文字、颜色和大小 🛠️ */
    --date-num: "06-05";       /* 🟡 🌟 【此行可以自由修改日期数字】 🌟 🟡 */
    --date-text: " · 芒种";     /* 🟡 🌟 【此行可以自由修改文本内容】 🌟 🟡 */
    --date-num-color: #666666; /* 🟡 🌟 【此行可以自由修改日期颜色】 🌟 🟡 */
    --date-text-color: #999999;/* 🟡 🌟 【此行可以自由修改文本颜色】 🌟 🟡 */
    --date-font-size: 12px;    /* 🟡 🌟 【此行可以自由修改整体字号】 🌟 🟡 */
}

.tc-header-main {
    display: flex !important;
    justify-content: space-between !important;
    align-items: center !important;
    flex-direction: row-reverse !important;
}

.tc-avatar-area {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
}
.tc-avatar-frame {
    width: 30px !important;
    height: 30px !important;
    border-radius: 50% !important;
    border: 1px solid #e2e0da !important;
}
.tc-avatar-badge { display: none !important; }
.tc-meta-title {
    font-size: 13px !important;
    color: #777777 !important;
    font-weight: 500 !important;
}

.tc-meta-area {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    gap: 6px !important;
}
.tc-stat[data-label="page"], .tc-stat[data-label="words"], .tc-stat[data-label="time"] {
    display: none !important;
}

/* 完美重写日期：实现数字、文字独立颜色且都可以自定义 */
.tc-stat[data-label="date"] {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    visibility: hidden !important; /* 隐藏原厂文字 */
    position: relative !important;
    font-size: var(--date-font-size) !important;
}
.tc-stat[data-label="date"]::before {
    content: var(--date-num) !important;
    visibility: visible !important;
    color: var(--date-num-color) !important;
}
.tc-stat[data-label="date"]::after {
    content: var(--date-text) !important;
    visibility: visible !important;
    color: var(--date-text-color) !important;
    margin-left: 0px !important;
}

.tc-divider { display: none !important; }

.tc-header-user {
    border-bottom: 1px dashed #e8e6df !important;
    padding-bottom: 8px !important;
    margin-bottom: 14px !important;
    color: #777777 !important;
    font-size: 12px !important;
    text-align: right !important;
}

/* ==========================================
   六、宽行距大字极简排版（勿动）
   ========================================== */
.tm-body-char, .tm-body-user {
    font-size: 16px !important;
    line-height: 1.9 !important;
    color: #111111 !important;
    letter-spacing: 0px !important;
}

.tm-para-block { margin-bottom: 10px !important; }
.tm-bold { color: #000000 !important; font-weight: 700 !important; }
.tm-action { color: #666666 !important; font-style: italic !important; }
.tm-quote-block { border-left: 2px solid #111111 !important; padding-left: 12px !important; margin: 10px 0 !important; }
.tm-del { color: #bbbbbb !important; text-decoration: line-through !important; }

/* ==========================================
   七、底部输入栏区域（勿动）
   ========================================== */
.tm-compose {
    background: #ffffff !important;
    border: 1px solid #e2e0da !important;
    border-radius: 16px !important;

    position: fixed !important;
    bottom: 0 !important;
    left: 14px !important;
    right: 14px !important;
    z-index: 999 !important;

    margin-bottom: calc(env(safe-area-inset-bottom, 12px) + 4px) !important; 
    padding: 12px 14px !important;

    box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.02), 0 4px 16px rgba(0, 0, 0, 0.03) !important;
}

.tm-compose-toolbar { 
    background: transparent !important; 
    border: none !important; 
    padding: 0 2px 8px 2px !important; 
    gap: 14px !important; 
}
.tm-regen-btn { 
    color: #666666 !important; 
    background: #f7f6f0 !important; 
    border: 1px solid #e2e0da !important; 
    border-radius: 8px !important; 
    font-size: 12px !important; 
    padding: 4px 10px !important; 
}
.tm-regen-btn.active { 
    color: #000000 !important; 
    background: #e8e6df !important; 
    border-color: #d2d0c9 !important; 
}

.tm-compose-row { 
    gap: 10px !important; 
    align-items: center !important;
}

.tm-input { 
    background: #f7f6f0 !important; 
    border: 1px solid #e8e6df !important; 
    border-radius: 10px !important; 
    color: #111111 !important; 
    padding: 10px 12px !important; 
}

.tm-send-btn { 
    background: #111111 !important; 
    color: #ffffff !important; 
    border-radius: 10px !important; 
    width: 40px !important; 
    height: 40px !important; 
    display: flex !important; 
    align-items: center !important; 
    justify-content: center !important; 
}

/* ==========================================
   八、多尺寸屏幕响应式适配
   ========================================== */
@media screen and (max-width: 360px) {
    .tm-header { left: 8px !important; right: 8px !important; }
    .tm-compose { left: 8px !important; right: 8px !important; }
    .tm-story { padding-top: calc(env(safe-area-inset-top, 20px) + 60px) !important; }
}

@media screen and (min-width: 600px) {
    .tm-header, .tm-story, .tm-compose { max-width: 600px !important; margin-left: auto !important; margin-right: auto !important; }
}

/* ============================================
   「冬雾」主题 v3
   ============================================ */

:root {
  --header-bg-url: url('https://pic1.imgdb.cn/item/6a217687f0d1d8911fa9d5c8.png');
  /* ↑ 换底图改这里 */
  --text-main: #2a2a2a;
  --text-mute: rgba(80, 85, 95, 0.52);
  --bubble-bg: rgba(255, 255, 255, 0.95);
  --border-light: rgba(175, 185, 190, 0.22);
}

/* ─── 纯白背景 ─── */
#this-moment-screen { background: #ffffff !important; }
.tm-bg-overlay { background: rgba(255,255,255,0.96) !important; }
.tm-bg-image { filter: blur(60px) saturate(0.2) brightness(1.2) !important; }

/* ============================================
   HEADER · 紧凑版，参考图三草图
   ============================================ */

.tc-header {
  position: relative !important;
  overflow: hidden !important;
  border-radius: 0 0 20px 20px !important;
  padding: 0 !important;
}

/* 背景图：只在顶部露一小条 */
.tc-header::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background-image: var(--header-bg-url) !important;
  background-size: cover !important;
  background-position: center 20% !important;
  filter: brightness(0.7) saturate(0.45) !important;
  z-index: 0 !important;
}

/* 渐变：从下往上盖白，背景图只露顶部一条 */
.tc-header::after {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,0) 0%,
    rgba(255,255,255,0) 22%,
    rgba(255,255,255,0.78) 42%,
    rgba(255,255,255,1) 62%
  ) !important;
  z-index: 1 !important;
}

/* 主内容区：头像左 + 信息右，紧凑 */
.tc-header-main {
  position: relative !important;
  z-index: 2 !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 16px !important;
  /* 上padding控制背景图露出多少，数值越小背景图越窄 */
  padding: 48px 18px 18px 18px !important;
}

.tc-avatar-area {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  flex-shrink: 0 !important;
}

.tc-avatar-frame {
  width: 72px !important;
  height: 72px !important;
  border-radius: 50% !important;
  border: 2.5px solid rgba(255,255,255,0.95) !important;
  box-shadow: 0 3px 12px rgba(0,0,0,0.14) !important;
  overflow: hidden !important;
  background: white !important;
}

.tc-avatar-img {
  border-radius: 50% !important;
  object-fit: cover !important;
}

.tc-avatar-badge { display: none !important; }

/* 右侧信息：紧凑排列 */
.tc-meta-area {
  display: flex !important;
  flex-direction: column !important;
  gap: 5px !important;
  flex: 1 !important;
}

.tc-meta-title {
  font-size: 17px !important;
  font-weight: 600 !important;
  color: #1a1a1a !important;
  letter-spacing: 0.1px !important;
  line-height: 1.2 !important;
}

.tc-meta-subtitle {
  display: block !important;
  min-height: 12px !important;
}
.tc-meta-subtitle::before {
  content: "L'amour du ciel · La La Land" !important;
  /* ↑ 简介文字改这里 */
  font-size: 11px !important;
  color: var(--text-mute) !important;
  letter-spacing: 0.4px !important;
}

/* 数据栏：三列一行 */
.tc-meta-stats {
  display: flex !important;
  flex-direction: row !important;
  gap: 18px !important;
  align-items: flex-start !important;
  margin-top: 2px !important;
}

.tc-stat {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  color: #1a1a1a !important;
  gap: 1px !important;
}

.tc-stat[data-label="page"]::after {
  content: 'Posts' !important;
  display: block !important;
  font-size: 9.5px !important;
  font-weight: 400 !important;
  color: var(--text-mute) !important;
}
.tc-stat[data-label="words"]::after {
  content: 'Followers' !important;
  display: block !important;
  font-size: 9.5px !important;
  font-weight: 400 !important;
  color: var(--text-mute) !important;
}
.tc-stat[data-label="date"]::after {
  content: 'Likes' !important;
  display: block !important;
  font-size: 9.5px !important;
  font-weight: 400 !important;
  color: var(--text-mute) !important;
}
.tc-stat[data-label="time"] { display: none !important; }

.tc-divider { display: none !important; }

/* ============================================
   正文气泡 · 角色（强制居中）
   ============================================ */

.tm-para-char {
  background: var(--bubble-bg) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border: 1px solid var(--border-light) !important;
  border-radius: 18px !important;
  box-shadow: 0 2px 14px rgba(0,0,0,0.05) !important;
  position: relative !important;
  overflow: hidden !important;
  -webkit-tap-highlight-color: transparent !important;
}

/* 右下角底纹小字 */
.tm-para-char::before {
  content: "L'amour du ciel" !important;
  position: absolute !important;
  right: 12px !important;
  bottom: 8px !important;
  font-size: 9px !important;
  font-weight: 300 !important;
  letter-spacing: 2.5px !important;
  color: rgba(110, 130, 150, 0.12) !important;
  pointer-events: none !important;
  z-index: 0 !important;
  white-space: nowrap !important;
}

/* 正文强制居中 */
.tm-body-char {
  color: var(--text-main) !important;
  font-size: 13px !important;
  line-height: 2.1 !important;
  letter-spacing: 0.2px !important;
  text-align: center !important;
  position: relative !important;
  z-index: 1 !important;
  -webkit-font-smoothing: antialiased !important;
}

.tm-para-block {
  text-align: center !important;
}

/* ─── 对话：灰底块，居中 ─── */
.tm-quote-block {
  display: block !important;
  background: rgba(190, 195, 205, 0.13) !important;
  border-left: none !important;
  border-radius: 8px !important;
  padding: 7px 14px !important;
  margin: 4px 0 !important;
  color: rgba(38, 50, 65, 0.85) !important;
  font-size: 13px !important;
  line-height: 1.9 !important;
  text-align: center !important;
}

/* ─── 动作：斜体灰蓝 ─── */
.tm-action {
  color: rgba(95, 115, 140, 0.68) !important;
  font-style: italic !important;
  letter-spacing: 0.5px !important;
}

/* ─── 心理/强调：浅底高亮 ─── */
.tm-bold {
  color: #28384a !important;
  background: rgba(110, 130, 150, 0.1) !important;
  border-radius: 3px !important;
  padding: 0 3px !important;
  font-weight: 600 !important;
}

.tm-del { color: rgba(155,160,170,0.45) !important; }

/* ============================================
   正文气泡 · 用户（与角色对齐，不居中跑）
   ============================================ */

.tm-para-user {
  background: rgba(255,255,255,0.88) !important;
  border: 1px solid var(--border-light) !important;
  border-radius: 18px !important;
  /* 关键：取消任何自动margin，与角色气泡左右对齐 */
  margin-left: 0 !important;
  margin-right: 0 !important;
  align-self: stretch !important;
  -webkit-tap-highlight-color: transparent !important;
}

.tm-body-user {
  color: rgba(48, 52, 62, 0.76) !important;
  font-size: 13px !important;
  line-height: 2.0 !important;
  text-align: center !important;
  -webkit-font-smoothing: antialiased !important;
}

/* 用户 header 区（头像+名字） */
.tc-header-user {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 10px !important;
  padding: 14px 16px 8px !important;
}

.tc-avatar-frame-user {
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  border: 2px solid rgba(200,205,215,0.45) !important;
  flex-shrink: 0 !important;
  overflow: hidden !important;
}

.tc-avatar-badge-user {
  display: block !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  color: #1a1a1a !important;
}

/* ============================================
   顶部导航栏
   ============================================ */

.tm-header {
  background: rgba(255,255,255,0.9) !important;
  backdrop-filter: blur(22px) !important;
  -webkit-backdrop-filter: blur(22px) !important;
  border-bottom: 1px solid var(--border-light) !important;
  padding-top: max(10px, calc(10px + var(--nuo-safe-top, 0px))) !important;
}

.tm-header-name { color: #1a1a1a !important; font-size: 14px !important; font-weight: 500 !important; }
.tm-btn-icon { color: #383838 !important; }
.tm-top-vs { color: rgba(100,108,118,0.25) !important; }
.tm-header-avatar { border: 1.5px solid rgba(175,185,190,0.38) !important; border-radius: 50% !important; }

/* ============================================
   工具栏
   ============================================ */

.tm-compose {
  background: rgba(255,255,255,0.94) !important;
  backdrop-filter: blur(22px) !important;
  -webkit-backdrop-filter: blur(22px) !important;
  border-top: 1px solid var(--border-light) !important;
  padding-bottom: calc(8px + var(--nuo-safe-bottom, 0px)) !important;
}

.tm-compose-toolbar {
  background: rgba(245,245,248,0.6) !important;
  border-radius: 22px !important;
  border: 1px solid rgba(195,200,210,0.25) !important;
  padding: 4px 12px !important;
  margin: 0 6px 4px 6px !important;
}

.tm-regen-btn { color: rgba(35,40,50,0.55) !important; border: none !important; background: transparent !important; }
.tm-compose-toolbar > .tm-regen-btn svg { display: none !important; }
