}

.tc-meta-subtitle {
  display: block !important;
  width: 100% !important;
  text-align: left !important;
  padding: 0 !important;
  margin: 0 0 4px 0 !important;
  min-height: auto !important;
}

.tc-meta-subtitle::before {
  content: '预　习' !important;
  display: block !important;
  font-size: var(--preview-title-size) !important;
  color: var(--theme-blue) !important;
  font-family: 'Noto Serif SC', serif !important;
  font-weight: 700 !important;
  letter-spacing: 6px !important;
  margin-bottom: 6px !important;
}

.tc-meta-extra-1 {
  display: block !important;
  width: 100% !important;
  text-align: left !important;
  padding: 0 !important;
  margin: 0 0 4px 0 !important;
}

.tc-meta-extra-1::before {
  content: '◎　对于缘分，你好像永远都猜不透。你猜测初见与别离，你猜测注定与偶然，却任由缘分保持它的缄默，将一切刻骨铭心化作心底那条暗涌的河。' !important;
  font-size: var(--preview-font-size) !important;
  color: var(--theme-blue) !important;
  font-family: 'Noto Serif SC', serif !important;
  line-height: 1.5 !important;
}

.tc-meta-extra-2 {
  display: block !important;
  width: 100% !important;
  text-align: left !important;
  padding: 0 !important;
  margin: 0 !important;
}

.tc-meta-extra-2::before {
  content: '◎　我们之间的关系像是生了锈，用力打磨之后，好像和以往没什么不同，只是少了些重量。' !important;
  font-size: var(--preview-font-size) !important;
  color: var(--theme-blue) !important;
  font-family: 'Noto Serif SC', serif !important;
  line-height: 1.5 !important;
}

.tc-header-deco-bottom {
  display: none !important;
}

.tc-divider {
  margin: 0 20px !important;
  border: none !important;
  border-bottom: 1px solid #e8e8e8 !important;
}

.tc-divider-text::before {
  content: '' !important;
}

/* §12 统计栏 */
.tc-meta-stats {
  position: static !important;
  display: flex !important;
  flex-direction: row !important;
  justify-content: space-between !important;
  align-items: center !important;
  gap: 0 !important;
  flex-wrap: nowrap !important;
  padding: 8px 20px !important;
  margin: 4px 0 0 0 !important;
  border-top: 0.8px solid #ddd !important;
  background: #ffffff !important;
  width: 100% !important;
  box-sizing: border-box !important;
}

.tc-stat {
  background: transparent !important;
  color: #888 !important;
  border: none !important;
  border-radius: 0 !important;
  font-size: 11px !important;
  padding: 0 !important;
  font-family: 'Noto Serif SC', serif !important;
  line-height: 1 !important;
}

.tc-stat:first-child {
  padding-left: 0 !important;
}

.tc-stat[data-label="page"] {
  color: #333 !important;
  font-weight: 600 !important;
}

.tc-stat[data-label="words"] {
  color: #666 !important;
}

.tc-stat[data-label="date"],
.tc-stat[data-label="time"] {
  color: #999 !important;
}

/* §13 Header — 用户消息（拓展阅读·蓝色） */
.tc-header-user {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  padding: 0 !important;
  background: transparent !important;
  border-bottom: none !important;
  gap: 0 !important;
}

.tc-avatar-frame-user {
  width: 0 !important;
  height: 0 !important;
  border: none !important;
  overflow: hidden !important;
  display: none !important;
}

.tc-avatar-badge-user {
  display: none !important;
}

.tc-header-user::before {
  content: '拓展阅读' !important;
  display: block !important;
  width: 100% !important;
  text-align: center !important;
  padding: 14px 20px 8px 20px !important;
  font-size: 15px !important;
  font-weight: 700 !important;
  color: var(--theme-blue) !important;
  font-family: 'Noto Serif SC', serif !important;
  letter-spacing: 6px !important;
  border-bottom: 1px solid var(--theme-blue) !important;
  margin: 0 20px !important;
}
/* §14 输入区 */
.tm-compose {
  background: #ffffff !important;
  border-top: 1px solid #e0e0e0 !important;
  backdrop-filter: none !important;
  box-shadow: 0 -1px 4px rgba(0,0,0,0.03) !important;
}

.tm-compose-toolbar {
  background: transparent !important;
  border: none !important;
  border-bottom: 1px solid #f0f0f0 !important;
  padding: 5px 10px !important;
}

.tm-compose-row {
  gap: 8px !important;
  padding: 8px 10px !important;
}

.tm-input {
  background: #f8f8f8 !important;
  color: #1a1a1a !important;
  border: 1px solid #e0e0e0 !important;
  border-radius: 4px !important;
  font-size: 15px !important;
  font-family: 'Noto Serif SC', serif !important;
  line-height: 1.8 !important;
  caret-color: #333 !important;
}

.tm-input:focus {
  border-color: #4a90d9 !important;
  box-shadow: 0 0 0 2px rgba(74,144,217,0.08) !important;
  background: #fff !important;
}

.tm-input::placeholder {
  color: rgba(0,0,0,0.2) !important;
  font-family: 'Noto Serif SC', serif !important;
}

.tm-send-btn {
  background: #f0f0f0 !important;
  color: #ccc !important;
  border-radius: 4px !important;
  width: 40px !important;
  height: 40px !important;
}

.tm-send-btn.ready {
  color: #fff !important;
  background: #333 !important;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15) !important;
}

.tm-regen-btn {
  color: #888 !important;
  border-color: #e0e0e0 !important;
  background: transparent !important;
  border-radius: 4px !important;
  font-family: 'Noto Serif SC', serif !important;
  font-size: 12px !important;
}

.tm-regen-btn:active {
  background: #f0f0f0 !important;
  color: #333 !important;
}

.tm-regen-btn.active {
  background: rgba(0,0,0,0.05) !important;
  color: #333 !important;
  border-color: #999 !important;
}

.tm-compose-toolbar > .tm-regen-btn:nth-of-type(1) {
  color: #666 !important;
}

.tm-compose-toolbar > .tm-regen-btn:nth-of-type(2) {
  color: #666 !important;
}

.tm-compose-toolbar > .tm-regen-btn:nth-of-type(3) {
  color: #666 !important;
}

.tm-compose-toolbar > .tm-regen-btn:nth-of-type(4) {
  color: #666 !important;
}

.tm-compose-toolbar > .tm-regen-btn:nth-of-type(5) {
  color: #b8886e !important;
}

/* §15 建议面板 */
.tm-suggestions-btn {
  color: #888 !important;
  background: transparent !important;
  border: 1px solid #e0e0e0 !important;
  border-radius: 4px !important;
}

.tm-suggestions-btn.active {
  background: #f5f5f5 !important;
}

.tm-suggestions-chevron {
  color: #666 !important;
}

.tm-suggestions-chevron.flipped {
  transform: rotate(180deg) !important;
}

.tm-suggestions-panel {
  background: #ffffff !important;
  border: 1px solid #e0e0e0 !important;
  border-radius: 6px !important;
  max-height: 300px !important;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.06) !important;
}

.tm-suggestion-item {
  background: #fafafa !important;
  border: 1px solid #eee !important;
  border-radius: 3px !important;
  padding: 10px 12px !important;
}

.tm-suggestion-direction {
  color: #4a90d9 !important;
  font-size: 11px !important;
}

.tm-suggestion-text-btn {
  background: transparent !important;
  border-radius: 2px !important;
}

.tm-suggestion-text {
  color: #333 !important;
  font-size: 13px !important;
  line-height: 1.75 !important;
  font-family: 'Noto Serif SC', serif !important;
}

.tm-suggestion-reroll {
  color: #666 !important;
  background: #f5f5f5 !important;
  border-radius: 3px !important;
}

.tm-suggestion-dot {
  background: #999 !important;
  width: 5px !important;
  height: 5px !important;
}

.tm-suggestion-error {
  color: #c0564b !important;
  font-size: 12px !important;
}

/* §16 右键菜单 */
.tm-context-menu {
  background: #ffffff !important;
  border: 1px solid #e0e0e0 !important;
  border-radius: 6px !important;
  box-shadow: 0 4px 20px rgba(0,0,0,0.1) !important;
}

.tm-context-menu button {
  color: #333 !important;
  background: transparent !important;
  font-size: 13.5px !important;
  font-family: 'Noto Serif SC', serif !important;
}

.tm-context-menu button:active {
  background: #f5f5f5 !important;
}

.tm-ctx-delete {
  color: #c0564b !important;
}

/* §17 编辑模式 */
.tm-edit-textarea {
  background: #ffffff !important;
  color: #1a1a1a !important;
  border: 1.5px solid #4a90d9 !important;
  border-radius: 2px !important;
  font-family: 'Noto Serif SC', serif !important;
  font-size: 15px !important;
  line-height: 2.0 !important;
}

.tm-edit-confirm {
  color: #fff !important;
  background: #333 !important;
  border-radius: 3px !important;
}

.tm-edit-cancel {
  color: #999 !important;
}

/* §18 多选模式 */
.tm-multiselect-bar {
  background: #fff !important;
  border-top: 1px solid #e0e0e0 !important;
}

.tm-ms-count {
  color: #333 !important;
  font-size: 13px !important;
  font-family: 'Noto Serif SC', serif !important;
}

.tm-ms-cancel {
  background: #f5f5f5 !important;
  color: #666 !important;
  border-radius: 3px !important;
}

.tm-ms-delete {
  background: rgba(192,86,75,0.08) !important;
  color: #c0564b !important;
  border-radius: 3px !important;
}

/* §19 历史浏览 */
.tm-history-bar {
  background: #fff !important;
