  border-radius: 3px !important;
}

/* §20 加载中 */
.tm-loading-container {
  background: rgba(255,255,255,0.7) !important;
}

.tm-loading-text {
  color: #666 !important;
  font-size: 14px !important;
  font-family: 'Noto Serif SC', serif !important;
}

/* §21 语音播放 */
.tm-voice-controls {
  gap: 8px !important;
  margin-top: 8px !important;
  padding: 6px 0 2px !important;
}

.tm-voice-btn {
  background: #f5f5f5 !important;
  color: #555 !important;
  border-radius: 3px !important;
  padding: 4px 10px !important;
}

.tm-voice-btn.playing {
  background: #eee !important;
  color: #333 !important;
}

.tm-voice-btn.loading {
  opacity: 0.5 !important;
}

.tm-voice-icon {
  color: #555 !important;
}

.tm-voice-label {
  color: #888 !important;
  font-size: 12px !important;
}

.tm-voice-spinner {
  color: #555 !important;
}

.tm-voice-wave {
  gap: 2px !important;
}

.tm-voice-wave span {
  background: #555 !important;
  width: 3px !important;
  border-radius: 2px !important;
}

/* §22 翻译 */
.tm-translation-section {
  border-left: 2px dotted #4a90d9 !important;
