  background: transparent !important;
  border-radius: 3px !important;
  font-family: 'Noto Serif SC', serif !important;
  font-size: 13px !important;
  padding: 8px 0 !important;
}

.tm-session-new-btn:active {
  background: #f5f5f5 !important;
}
